const request=(path,{token,method='GET',body,prefer}={})=>{const mutation=!['GET','HEAD'].includes(method.toUpperCase());if(mutation&&path.startsWith('/rest/v1/ordens_servico')&&!hasPermission('editOrders'))return Promise.reject(new Error('Seu usuário possui acesso somente para visualizar ordens de serviço.'));if(mutation&&path.startsWith('/rest/v1/lancamentos_financeiros')&&currentEmail()!==OWNER_EMAIL)return Promise.reject(new Error('O Financeiro está em modo somente leitura para este usuário.'));return fetch(`${SUPABASE_URL}${path}`,{method,headers:headers(token,prefer?{Prefer:prefer}:{}),body:body===undefined?undefined:JSON.stringify(body)}).then(json)};
async function readPages(path,token){const rows=[],separator=path.includes('?')?'&':'?';for(let offset=0;;offset+=1000){const page=await request(`${path}${separator}limit=1000&offset=${offset}`,{token});rows.push(...page);if(page.length<1000)break}return rows}
