export async function createOperationalBackup(){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode criar cópias de segurança.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const entries=await Promise.all(BACKUP_TABLES.map(async table=>[table,await readAllTableRows(session,table)])),tables=Object.fromEntries(entries);return{format:'cortez-garage-operational-backup',version:2,mode:'exact',projectRef:'pqldixrfvmkwkwbbysyl',createdAt:new Date().toISOString(),tables,counts:Object.fromEntries(entries.map(([table,rows])=>[table,rows.length]))}}
