async function applyOperationalBackup(session,tables){for(const table of['clientes','veiculos','ordens_servico','estoque'])await restoreRows(session,table,tables[table]);await restoreAppointments(session,tables.agendamentos);for(const table of['lancamentos_financeiros','sincronizacao'])await restoreRows(session,table,tables[table]);for(const table of['lancamentos_financeiros','sincronizacao','agendamentos','ordens_servico','estoque','veiculos','clientes'])await deleteRowsOutsideBackup(session,table,tables[table])}
export async function restoreOperationalBackup(backup){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode restaurar cópias de segurança.');if(backup?.format!=='cortez-garage-operational-backup'||![1,2].includes(backup?.version)||!backup.tables)throw new Error('Arquivo de backup inválido ou incompatível.');if(backup.projectRef&&backup.projectRef!=='pqldixrfvmkwkwbbysyl')throw new Error('Este backup pertence a outro projeto.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');for(const table of BACKUP_TABLES){const rows=backup.tables[table];if(!Array.isArray(rows))throw new Error(`O backup não contém a tabela ${table}.`)}const before=Object.fromEntries(await Promise.all(BACKUP_TABLES.map(async table=>[table,await readAllTableRows(session,table)])));try{await applyOperationalBackup(session,backup.tables)}catch(error){try{await applyOperationalBackup(session,before)}catch(rollbackError){console.error('Falha ao reverter restauração',rollbackError)}throw error}const verified=Object.fromEntries(await Promise.all(BACKUP_TABLES.map(async table=>[table,(await readAllTableRows(session,table)).length])));for(const table of BACKUP_TABLES)if(verified[table]!==backup.tables[table].length)throw new Error(`A verificação da tabela ${table} falhou após a restauração.`);return{restored:verified,createdAt:backup.createdAt}}

