const getDeviceId=()=>{let id=localStorage.getItem(DEVICE_KEY);if(!id){id=crypto.randomUUID();localStorage.setItem(DEVICE_KEY,id)}return id};
let usageTracker=null;
function usageDuration(now=Date.now()){if(!usageTracker)return 0;if(usageTracker.active)usageTracker.seconds+=Math.max(0,Math.min(USAGE_HEARTBEAT_MS*2,now-usageTracker.lastTick))/1000;usageTracker.lastTick=now;return Math.round(usageTracker.seconds)}
function usageBody(ended=false){const now=new Date().toISOString();return{last_seen_at:now,active_seconds:usageDuration(),ended_at:ended?now:null}}
async function flushUsage(ended=false){if(!usageTracker)return;const tracker=usageTracker,session=getSession();if(!session?.access_token)return;await request(`/rest/v1/app_user_sessions?id=eq.${encodeURIComponent(tracker.id)}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body:usageBody(ended)});if(ended){clearInterval(tracker.timer);usageTracker=null}}
function finishUsageTracking(){if(!usageTracker)return;const tracker=usageTracker,session=getSession(),body=usageBody(true);clearInterval(tracker.timer);usageTracker=null;if(!session?.access_token)return;fetch(`${SUPABASE_URL}/rest/v1/app_user_sessions?id=eq.${encodeURIComponent(tracker.id)}`,{method:'PATCH',headers:headers(session.access_token,{Prefer:'return=minimal'}),body:JSON.stringify(body),keepalive:true}).catch(()=>{})}
export async function startUsageTracking(){if(usageTracker||currentEmail()===OWNER_EMAIL)return;const session=await refreshSession();if(!session?.access_token||!session.user?.id)return;const now=new Date().toISOString(),rows=await request('/rest/v1/app_user_sessions',{token:session.access_token,method:'POST',prefer:'return=representation',body:{user_id:session.user.id,user_email:currentEmail(),started_at:now,last_seen_at:now,active_seconds:0}}),row=rows?.[0];if(!row)return;usageTracker={id:row.id,seconds:0,lastTick:Date.now(),active:document.visibilityState==='visible',timer:0};usageTracker.timer=setInterval(()=>flushUsage(false).catch(error=>console.warn('Não foi possível atualizar o tempo de uso:',error)),USAGE_HEARTBEAT_MS);document.addEventListener('visibilitychange',()=>{if(!usageTracker)return;if(document.visibilityState==='hidden'){flushUsage(false).catch(()=>{});usageTracker.active=false}else{usageTracker.lastTick=Date.now();usageTracker.active=true;flushUsage(false).catch(()=>{})}});addEventListener('pagehide',finishUsageTracking,{once:true})}
export async function readUserUsage(email){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode consultar o histórico de acessos.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');email=clean(email).toLowerCase();const rows=await request(`/rest/v1/app_user_sessions?select=id,user_email,started_at,last_seen_at,ended_at,active_seconds&user_email=eq.${encodeURIComponent(email)}&order=started_at.desc&limit=500`,{token:session.access_token});return(rows||[]).map(row=>({id:row.id,email:row.user_email,startedAt:row.started_at,lastSeenAt:row.last_seen_at,endedAt:row.ended_at||'',activeSeconds:Number(row.active_seconds)||0}))}
export function signOut(){finishUsageTracking();localStorage.removeItem(SESSION_KEY);location.reload()}
async function bindSessionToDevice(session,{relink=false}={}){const deviceId=getDeviceId(),metadata=session.user?.user_metadata||{},bound=metadata.device_id,email=String(session.user?.email||'').toLowerCase(),owner=email===OWNER_EMAIL;if(bound&&bound!==deviceId&&!owner&&!relink)throw new Error('Este acesso foi transferido para outro celular. Entre novamente para usar este aparelho.');if(!bound||bound!==deviceId){const user=await request('/auth/v1/user',{token:session.access_token,method:'PUT',body:{data:{...metadata,device_id:deviceId,device_relinked_at:bound?new Date().toISOString():metadata.device_relinked_at}}});session.user=user}localStorage.setItem(SESSION_KEY,JSON.stringify(session));return session}
export async function signIn(email,password){const session=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email,password}});return bindSessionToDevice(session,{relink:true})}
export async function signUp(name,email,password){const result=await request('/auth/v1/signup',{method:'POST',body:{email,password,data:{name:clean(name),device_id:getDeviceId()}}});if(!result.access_token)throw new Error('Cadastro criado. Confirme o e-mail e depois entre neste celular.');localStorage.setItem(SESSION_KEY,JSON.stringify(result));return result}
export async function refreshSession(){const current=getSession();if(!current?.refresh_token)return null;if((current.expires_at||0)*1000>Date.now()+60000)return bindSessionToDevice(current);let lastError;for(let attempt=0;attempt<3;attempt++){try{const session=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:current.refresh_token}});return bindSessionToDevice(session)}catch(error){lastError=error;if(attempt<2)await new Promise(resolve=>setTimeout(resolve,700*(attempt+1)))}}if(/refresh.?token|invalid.?token/i.test(lastError?.message||'')){localStorage.removeItem(SESSION_KEY);location.reload()}throw lastError}

export function renderLogin(onSuccess){
  let registering=false;
  const draw=()=>{
    document.querySelector('#app').innerHTML=`<main class="login-page"><form id="loginForm" class="login-card"><img src="./official-logo.png" alt="Cortez Garage"><h1>${registering?'Cadastrar este celular':'Acesso à oficina'}</h1><p>${registering?'Crie um usuário exclusivo para identificar este aparelho.':'Entre uma vez; o acesso ficará salvo neste celular.'}</p>${registering?'<label><span>Nome do usuário</span><input id="loginName" autocomplete="name" required></label>':''}<label><span>E-mail</span><input id="loginEmail" type="email" autocomplete="username" required></label><label><span>Senha</span><input id="loginPassword" type="password" minlength="6" autocomplete="${registering?'new-password':'current-password'}" required></label><button class="primary wide">${registering?'Criar acesso':'Entrar'}</button><button id="toggleRegistration" class="link wide" type="button">${registering?'Já tenho acesso':'Cadastrar usuário deste celular'}</button><small id="loginError" role="alert"></small></form></main>`;
    document.querySelector('#toggleRegistration').onclick=()=>{registering=!registering;draw()};
    document.querySelector('#loginForm').onsubmit=async event=>{
      event.preventDefault();const button=event.submitter,error=document.querySelector('#loginError');button.disabled=true;button.textContent=registering?'Cadastrando…':'Entrando…';error.textContent='';
      try{const email=document.querySelector('#loginEmail').value.trim(),password=document.querySelector('#loginPassword').value;if(registering)await signUp(document.querySelector('#loginName').value,email,password);else await signIn(email,password);await onSuccess()}
      catch(reason){error.textContent=reason.message;button.disabled=false;button.textContent=registering?'Criar acesso':'Entrar'}
    };
  };
  draw();
}

