function repairedBudget(row,extras){const source=extras.budget&&typeof extras.budget==='object'?extras.budget:{},parts=Array.isArray(source.parts)?source.parts.filter(Boolean):[],services=Array.isArray(source.services)?source.services.filter(Boolean):[],partsValue=Number(row.valor_pecas)||0,labor=Number(row.mao_obra)||0;if(!parts.length&&partsValue>0)parts.push({description:clean(extras.parts)||'Peças e materiais — descrição anterior não recuperada',cost:partsValue,margin:0,quantity:1,value:partsValue,refused:false,recovered:true});if(!services.length&&labor>0)services.push({description:clean(extras.services)||'Mão de obra — descrição anterior não recuperada',mechanic:clean(row.mecanico),value:labor,commissionRate:.5,refused:false,recovered:true});return{...source,parts,services,partsTotal:parts.filter(item=>!item.refused).reduce((sum,item)=>sum+Math.max(1,Number(item.quantity)||1)*Number(item.value||0),0),servicesTotal:services.filter(item=>!item.refused).reduce((sum,item)=>sum+Number(item.value||0),0)}}
function normalizedOrderAdvances(extras,orderId=''){const saved=Array.isArray(extras?.advances)?extras.advances:[],rows=saved.map((item,index)=>({id:clean(item?.id)||`legacy-${index+1}`,amount:Math.max(0,Number(item?.amount)||0),paymentType:clean(item?.paymentType),createdAt:item?.createdAt||item?.date||'',reference:clean(item?.reference)||`adiantamento-os-${orderId}-${clean(item?.id)||index+1}`})).filter(item=>item.amount>0);if(rows.length)return rows;const amount=Math.max(0,Number(extras?.advance)||0);return amount?[{id:'legacy',amount,paymentType:clean(extras?.advancePayment),createdAt:extras?.advanceAt||'',reference:`adiantamento-os-${orderId}`}]:[]}
function mapOrder(row,clients,vehicles){const extras=row.dados_extras||{},budget=repairedBudget(row,extras),client=clients.find(item=>item.id===row.cliente_id)||extras.client||{},vehicle=vehicles.find(item=>item.id===row.veiculo_id)||extras.vehicle||{},labor=Number(row.mao_obra)||Number(budget.servicesTotal)||0,partsValue=Number(row.valor_pecas)||Number(budget.partsTotal)||0,discount=Number(row.desconto)||0,total=Number(row.total)||Number(budget.total)||labor+partsValue-discount,advances=normalizedOrderAdvances(extras,row.id),advance=advances.reduce((sum,item)=>sum+item.amount,0),latestAdvance=advances.at(-1);return{id:row.id,number:String(row.numero).padStart(4,'0'),created:row.data_entrada,client,vehicle,complaint:row.reclamacao||'',diagnosis:row.diagnostico||'',notes:row.observacoes||'',damage:row.avarias||'',mechanic:row.mecanico||'',status:row.status,labor,partsValue,discount,total,advances,advance,advancePayment:latestAdvance?.paymentType||extras.advancePayment||'',advanceAt:latestAdvance?.createdAt||extras.advanceAt||null,payment:row.pagamento||'',checklist:row.checklist||[],photos:row.fotos||[],signature:'',services:extras.services||'',parts:extras.parts||'',budget,technicalReport:extras.technicalReport||null,closingReceipt:extras.closingReceipt||null,warranty:Boolean(extras.warranty),warrantyPayCommissions:Boolean(extras.warrantyPayCommissions),createdBy:extras.createdBy||null,updatedBy:extras.updatedBy||null,updatedAt:row.atualizado_em,deliveredAt:row.entregue_em||null}}
