async function readDatabase(token){const [clientRows,vehicleRows,orderRows]=await Promise.all([readPages('/rest/v1/clientes?select=*',token),readPages('/rest/v1/veiculos?select=*',token),readPages('/rest/v1/ordens_servico?select=*&order=numero.asc',token)]);const clients=clientRows.map(mapClient),vehicles=vehicleRows.map(mapVehicle),orders=orderRows.map(row=>mapOrder(row,clients,vehicles));return{clients,vehicles,orders,counter:Math.max(0,...orders.map(order=>Number(order.number)||0))+1}}
