// O fluxo guiado substitui requireServiceManagement('dar baixa em ordem de serviço') para que todo usuário autorizado a marcar a O.S. como pronta conclua a conferência.
export async function consumeStockForOrder(order,selections=[]){
  const session=await refreshSession();
  if(!session?.access_token)throw new Error('Sessão expirada');
  const movementId=encodeURIComponent(order.id),done=await request(`/rest/v1/sincronizacao?entidade=eq.estoque_saida&registro_id=eq.${movementId}&select=id&limit=1`,{token:session.access_token});
  if(done.length)return{alreadyProcessed:true,missing:[]};
  const rows=await request('/rest/v1/estoque?select=*',{token:session.access_token}),missing=[],used=[],groups=new Map();
  for(const [index,part]of(order.budget?.parts||[]).entries()){
    if(part.refused)continue;
    const chosen=selections.find(item=>Number(item.partIndex)===index),code=clean(part.code).toLowerCase(),description=clean(part.description).toLowerCase();
    const found=chosen?rows.find(row=>row.id===chosen.stockId):rows.find(row=>(code&&clean(row.codigo).toLowerCase()===code)||clean(row.descricao).toLowerCase()===description);
    const needed=Math.max(1,Number(part.quantity||1));
    if(!found){missing.push(part.description);continue}
    const saleValue=Math.max(Number(found.valor_unitario||0),Number(part.value||0));
    used.push({partIndex:index,stockId:found.id,description:part.description,quantity:needed,saleValue});
    const group=groups.get(found.id)||{row:found,quantity:0,saleValue:0,descriptions:[]};
    group.quantity+=needed;group.saleValue=Math.max(group.saleValue,saleValue);group.descriptions.push(part.description);groups.set(found.id,group);
  }
  for(const group of groups.values())if(group.quantity>Number(group.row.quantidade||0))missing.push(...group.descriptions);
  if(missing.length)return{alreadyProcessed:false,missing:[...new Set(missing)]};
  try{
    const result=await request('/rest/v1/rpc/processar_baixa_estoque',{token:session.access_token,method:'POST',body:{p_order_id:order.id,p_order_number:String(order.number),p_items:used}});
    return result||{alreadyProcessed:false,missing:[]}
  }catch(error){
    if(!/processar_baixa_estoque|schema cache|PGRST202/i.test(error.message||''))throw error;
    console.warn('A função transacional do estoque ainda não foi instalada; usando compatibilidade segura.',error)
  }
  const changed=[];
  try{
    for(const [stockId,group]of groups){
      const before=Number(group.row.quantidade||0),updated=await request(`/rest/v1/estoque?id=eq.${encodeURIComponent(stockId)}&quantidade=eq.${before}`,{token:session.access_token,method:'PATCH',prefer:'return=representation',body:{quantidade:before-group.quantity,valor_unitario:group.saleValue}});
      if(!updated.length)throw new Error(`O estoque de ${group.descriptions.join(', ')} mudou durante a baixa. Tente novamente.`);
      changed.push({stockId,before,saleValue:Number(group.row.valor_unitario||0)})
    }
  }catch(error){
    for(const item of changed.reverse())await request(`/rest/v1/estoque?id=eq.${encodeURIComponent(item.stockId)}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body:{quantidade:item.before,valor_unitario:item.saleValue}}).catch(()=>{});
    throw error
  }
  await request('/rest/v1/sincronizacao',{token:session.access_token,method:'POST',prefer:'return=minimal',body:{origem:'app',entidade:'estoque_saida',registro_id:order.id,dados:{ordem:order.number,pecas:used,faltantes:[]}}});
  return{alreadyProcessed:false,missing:[]}
}

