async function writeSupplierSettlements(data){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode alterar acertos de fornecedores.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const current=await supplierConfig(session),normalized={luizinho:normalizeSupplierRows(data?.luizinho,'luizinho'),retifica:normalizeSupplierRows(data?.retifica,'retifica'),luizinhoReturns:normalizeLuizinhoReturns(data?.luizinhoReturns)},body={origem:'app',entidade:'configuracao',registro_id:'acerto-fornecedores',dados:{...normalized,updatedAt:new Date().toISOString()}};if(current)await request(`/rest/v1/sincronizacao?id=eq.${encodeURIComponent(current.id)}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body});else await request('/rest/v1/sincronizacao',{token:session.access_token,method:'POST',prefer:'return=minimal',body});await syncLuizinhoPayables(session,normalized.luizinho,normalized.luizinhoReturns);return normalized}
export async function saveSupplierSettlement(type,record){type=supplierType(type);const data=await readSupplierSettlements(),date=supplierDate(record?.date),day=new Date(`${date}T12:00:00`).getDay();if(!date||!clean(record?.description))throw new Error('Informe data e descrição.');if(type==='luizinho'&&(day<1||day>5))throw new Error('As notas do Luizinho devem ser lançadas de segunda a sexta.');data[type].push({...record,id:record?.id||crypto.randomUUID(),date,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});return writeSupplierSettlements(data)}
export async function updateSupplierSettlement(type,id,changes){type=supplierType(type);const data=await readSupplierSettlements(),index=data[type].findIndex(item=>item.id===id);if(index<0)throw new Error('Lançamento do fornecedor não encontrado.');const date=supplierDate(changes?.date||data[type][index].date),day=new Date(`${date}T12:00:00`).getDay();if(type==='luizinho'&&(day<1||day>5))throw new Error('As notas do Luizinho devem ser lançadas de segunda a sexta.');data[type][index]={...data[type][index],...changes,id,date,updatedAt:new Date().toISOString()};return writeSupplierSettlements(data)}
