async function removeLuizinhoReturnFromStock(session,item){const rows=await request('/rest/v1/estoque?select=*',{token:session.access_token}),key=stockKey({code:item.code,description:item.description,application:item.brand}),found=rows.find(row=>stockKey(row)===key),available=Number(found?.quantidade||0);if(!found)throw new Error('A peça não foi encontrada no estoque.');if(available<item.quantity)throw new Error(`Estoque insuficiente para a devolução. Disponível: ${available}.`);await request(`/rest/v1/estoque?id=eq.${encodeURIComponent(found.id)}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body:{quantidade:available-item.quantity}})}

export async function saveLuizinhoReturn(record){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode registrar devoluções.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const data=await readSupplierSettlements(),note=data.luizinho.find(item=>item.id===clean(record?.noteId));if(!note)throw new Error('A nota original não foi encontrada.');const itemKey=stockKey({code:record?.code,description:record?.description,application:record?.brand}),source=note.items.find(item=>stockKey({code:item.code,description:item.description,application:item.brand})===itemKey);if(!source)throw new Error('A peça não pertence à nota selecionada.');const returned=data.luizinhoReturns.filter(item=>item.noteId===note.id&&stockKey({code:item.code,description:item.description,application:item.brand})===itemKey).reduce((sum,item)=>sum+item.quantity,0),quantity=Math.trunc(Number(record?.quantity)||0),remaining=source.quantity-returned;if(quantity<1||quantity>remaining)throw new Error(`Quantidade inválida. Restam ${Math.max(0,remaining)} unidade(s) disponíveis para devolução nesta nota.`);const date=supplierDate(record?.date);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw new Error('Informe a data da devolução.');const creditWeek=supplierWeek(record?.creditWeek||date).start,saved={id:crypto.randomUUID(),noteId:note.id,noteDate:note.date,date,creditWeek,code:source.code,brand:source.brand,description:source.description,quantity,unitValue:source.unitValue,amount:Number((quantity*source.unitValue).toFixed(2)),vehicle:note.vehicle,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};await removeLuizinhoReturnFromStock(session,saved);data.luizinhoReturns.push(saved);let result;try{result=await writeSupplierSettlements(data)}catch(error){const persisted=await readSupplierSettlements().catch(()=>null);if(persisted?.luizinhoReturns?.some(item=>item.id===saved.id))result=persisted;else{await applyLuizinhoStockDelta(session,[],[{...source,quantity}]).catch(()=>{});throw error}}await request('/rest/v1/sincronizacao',{token:session.access_token,method:'POST',prefer:'return=minimal',body:{origem:'app',entidade:'estoque_devolucao_luizinho',registro_id:saved.id,dados:saved}}).catch(()=>{});return result}

export async function updateLuizinhoReturnWeek(id,creditWeek){const data=await readSupplierSettlements(),index=data.luizinhoReturns.findIndex(item=>item.id===id);if(index<0)throw new Error('Devolução não encontrada.');data.luizinhoReturns[index]={...data.luizinhoReturns[index],creditWeek:supplierWeek(creditWeek).start,updatedAt:new Date().toISOString()};return writeSupplierSettlements(data)}
function validateLuizinhoNote(record){const date=supplierDate(record?.date),day=new Date(`${date}T12:00:00`).getDay(),items=normalizeLuizinhoItems(record?.items);if(day<1||day>5)throw new Error('As notas do Luizinho devem ser lançadas de segunda a sexta.');if(!items.length)throw new Error('Inclua pelo menos um item com descrição, quantidade e valor.');return{...record,date,items,description:items.map(item=>item.description).join(', '),amount:Number(items.reduce((sum,item)=>sum+item.total,0).toFixed(2))}}
export async function saveLuizinhoNote(record){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode alterar acertos de fornecedores.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const data=await readSupplierSettlements(),note=validateLuizinhoNote({...record,id:record?.id||crypto.randomUUID()}),movement=await request(`/rest/v1/sincronizacao?entidade=eq.estoque_entrada_luizinho&registro_id=eq.${encodeURIComponent(note.id)}&select=id&limit=1`,{token:session.access_token});if(!movement.length){await applyLuizinhoStockDelta(session,[],note.items);await request('/rest/v1/sincronizacao',{token:session.access_token,method:'POST',prefer:'return=minimal',body:{origem:'app',entidade:'estoque_entrada_luizinho',registro_id:note.id,dados:{itens:note.items,data:note.date}}})}const index=data.luizinho.findIndex(item=>item.id===note.id),saved={...note,stockApplied:true,createdAt:data.luizinho[index]?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(index>=0)data.luizinho[index]=saved;else data.luizinho.push(saved);return writeSupplierSettlements(data)}
export async function updateLuizinhoNote(id,changes){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode alterar acertos de fornecedores.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const data=await readSupplierSettlements(),index=data.luizinho.findIndex(item=>item.id===id);if(index<0)throw new Error('Nota do Luizinho não encontrada.');const previous=data.luizinho[index],note=validateLuizinhoNote({...previous,...changes,id});if(previous.stockApplied)await applyLuizinhoStockDelta(session,previous.items,note.items);data.luizinho[index]={...previous,...note,stockApplied:previous.stockApplied,updatedAt:new Date().toISOString()};return writeSupplierSettlements(data)}
