export async function saveFinanceRecord(record){
  if(record.category!=='Conta a pagar'||record.payableCategory===undefined)return saveFinanceRecordBase(record);
  const session=await refreshSession(),id=crypto.randomUUID();
  await savePayableCategory(session,id,record.payableCategory);
  return {...await saveFinanceRecordBase({...record,id}),payableCategory:record.payableCategory};
}
export async function updateFinanceRecord(id,record){
  const result=await updateFinanceRecordBase(id,record);
  if(record.category==='Conta a pagar'&&record.payableCategory!==undefined){
    try{await savePayableCategory(await refreshSession(),id,record.payableCategory)}catch(error){throw new Error('Conta atualizada, mas a categoria não foi salva. Abra Editar e tente novamente. '+error.message)}
    result.payableCategory=record.payableCategory;
  }
  return result;
}
